actions.script:
const OPS = {settings: 'update#CallHandlingSetting', storeRule: 'store#CallHandlingRule', deleteRule: 'delete#CallHandlingRule',
    storeList: 'store#CallerList', deleteList: 'delete#CallerList', addEntry: 'add#CallerListEntry', removeEntry: 'remove#CallerListEntry'}
const service = OPS[ec.web.parameters.op]
let out = {}
if (!service) ec.message.addError(ec.l10n.localize('Not a call handling change'))
else {
    const parameters = {}
    for (const name of ['callWaiting', 'mobileNumber', 'ringMobile', 'mobileScheduleId', 'hideCallerId', 'dnd', 'callHandlingRuleId', 'kindEnumId',
        'targetTypeEnumId', 'targetId', 'callerListId', 'commsScheduleId', 'scheduleWhen', 'sequenceNum', 'disabled', 'name', 'phoneNumber']) {
        const value = ec.web.parameters[name]
        if (value !== undefined && value !== null) parameters[name] = value
    }
    out = ec.service.sync().name('org.moqui.call.CallHandlingServices.' + service).parameters(parameters).requireNewTransaction(true)
        .disableAuthz().call() || {}
}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse(Object.assign({}, out, {errors, reasonCode: out.reasonCode || null}))
